actions.script:
if (!ec.message.hasError() && prepared) {
    const blocked = Array.from(prepared.rows || []).filter(row => row.outcome === 'blocked' || row.outcome === 'refused')
    ec.message.addMessage((preview == 'Y' ? 'Preview, nothing prepared: ' : 'Prepared: ') + (prepared.createdCount || 0) + ' inputs', preview == 'Y' ? 'info' : 'success')
    if (blocked.length) ec.message.addMessage('Not prepared: ' + blocked.map(row => row.personName + ' (' + row.message + ')').join('; '), 'warning')
}
